import React from "react";
import {
  BrowserRouter,
  Routes,
  Route
} from "react-router-dom";

import Sidebar from "./components/Sidebar";

import Dashboard from "./pages/Dashboard";
import Threats from "./pages/Threats";
import Incidents from "./pages/Incidents";
import Packets from "./pages/Packets";
import Settings from "./pages/Settings";

function App() {
  return (
    <BrowserRouter>
      <div style={styles.app}>
        <Sidebar />

        <Routes>
          <Route
            path="/"
            element={<Dashboard />}
          />

          <Route
            path="/threats"
            element={<Threats />}
          />

          <Route
            path="/incidents"
            element={<Incidents />}
          />

          <Route
            path="/packets"
            element={<Packets />}
          />

          <Route
            path="/settings"
            element={<Settings />}
          />
        </Routes>
      </div>
    </BrowserRouter>
  );
}

const styles = {
  app: {
    display: "flex",
    background: "#0f172a",
    color: "white",
    minHeight: "100vh"
  }
};

export default App;
